package com.campusplacement.controller;
import com.campusplacement.dto.ApiResponse; import com.campusplacement.entity.*; import com.campusplacement.repository.*; import com.campusplacement.service.PlacementService; import org.springframework.web.bind.annotation.*; import java.util.*; import java.util.stream.*;
@RestController @RequestMapping("/applications")
public class ApplicationController { private final ApplicationRepository repo; private final PlacementService service; public ApplicationController(ApplicationRepository r,StudentRepository s,PlacementDriveRepository d,PlacementService p){repo=r;service=p;}
 private Map<String,Object> view(Application a){Map<String,Object> m=new LinkedHashMap<>();m.put("id",a.getId());m.put("studentId",a.getStudent().getId());m.put("student",a.getStudent().getName());m.put("rollNumber",a.getStudent().getRollNumber());m.put("driveId",a.getDrive().getId());m.put("company",a.getDrive().getCompany().getName());m.put("role",a.getDrive().getJobRole());m.put("appliedDate",a.getAppliedDate());m.put("status",a.getStatus());m.put("registrationDetails",a.getRegistrationDetails());m.put("applicationLink",a.getDrive().getApplicationLink());return m;}
 @GetMapping public List<Map<String,Object>> all(){return repo.findAll().stream().map(this::view).collect(Collectors.toList());}
 @PostMapping("/apply") public ApiResponse apply(@RequestParam Integer studentId,@RequestParam Integer driveId,@RequestBody(required=false) Map<String,Object> details){String json=null;if(details!=null&&!details.isEmpty()){try{json=new com.fasterxml.jackson.databind.ObjectMapper().writeValueAsString(details);}catch(Exception e){throw new IllegalArgumentException("Invalid registration details");}}return new ApiResponse(true,"Application submitted",view(service.apply(studentId,driveId,json)));}
 @PutMapping("/{id}/status") public ApiResponse status(@PathVariable Integer id,@RequestParam String value){Application a=repo.findById(id).orElseThrow(()->new IllegalArgumentException("Application not found"));String status=value==null?"":value.trim().toUpperCase();if(!Arrays.asList("APPLIED","UNDER_REVIEW","SHORTLISTED","INTERVIEW_SCHEDULED","INTERVIEW_NOT_SCHEDULED","SELECTED","REJECTED").contains(status))throw new IllegalArgumentException("Invalid application status");a.setStatus(status);return new ApiResponse(true,"Application status updated",view(repo.save(a)));}
 @GetMapping("/student/{studentId}") public List<Map<String,Object>> byStudent(@PathVariable Integer studentId){return repo.findByStudentId(studentId).stream().map(this::view).collect(Collectors.toList());}
 @GetMapping("/drive/{driveId}") public List<Map<String,Object>> byDrive(@PathVariable Integer driveId){return repo.findByDriveId(driveId).stream().map(this::view).collect(Collectors.toList());}
}
